import re, os, json
from collections import defaultdict

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def native_record_block(text):
    m = re.findall(r"NATIVE RECORD\s*\n(.+?)\n\s*\n", text, re.S)
    if m: return m[-1].strip()
    m = re.findall(r"##\s*Native record\s*\n\s*\n(.+?)\n\s*\n", text, re.S)
    if m: return m[-1].strip()
    m = re.findall(r"Native record</h2>\s*<p>(.*?)</p>", text, re.S)
    if m: return m[-1].strip()
    m = re.findall(r'heading="Native record"[^>]*>\s*<text>(.*?)</text>', text, re.S)
    if m: return m[-1].strip()
    m = re.findall(r'metadata,\d{4}-\d{2}-\d{2},body,"(.*?)",', text)
    if m: return m[-1].strip()
    m = re.findall(r"Native record\s*\n(.+?)\n", text, re.S)
    if m: return m[-1].strip()
    return None

def get_field(text, label):
    for pat in [rf"^{label}:\s*(.+)$", rf"\|\s*{label}\s*\|\s*(.+?)\s*\|", rf"<{label}>(.*?)</{label}>", rf',{label},"?(.*?)"?,']:
        m = re.search(pat, text, re.M if '^' in pat else 0)
        if m: return m.group(1).strip()
    return None

recs = {}
for folder in sorted(os.listdir(base)):
    fdir = os.path.join(base, folder)
    if not os.path.isdir(fdir): continue
    for f in sorted(os.listdir(fdir)):
        p = os.path.join(fdir, f)
        if f.endswith(".xlsx"): continue
        text = open(p, encoding="utf-8", errors="replace").read()
        rid = "CB-DOC-031-" + re.search(r"CB-DOC-031-(\d{3})", text).group(1)
        recs[rid] = dict(
            pk=get_field(text,"PORTFOLIO KEY") or get_field(text,"Portfolio key") or get_field(text,"portfolio_key"),
            role=get_field(text,"EVIDENCE ROLE") or get_field(text,"Evidence role"),
            entity=get_field(text,"ENTITY KEY") or get_field(text,"Immutable entity") or get_field(text,"immutable_entity_key"),
            subject=get_field(text,"SUBJECT") or get_field(text,"Subject") or get_field(text,"subject"),
            custodian=get_field(text,"CUSTODIAN") or get_field(text,"Custodian"),
            reviewer=get_field(text,"REVIEWER") or get_field(text,"Reviewer"),
            system=get_field(text,"SOURCE SYSTEM") or get_field(text,"Source system") or get_field(text,"source_system"),
            body=native_record_block(text), fmt=f.split(".")[-1], folder=folder, file=f
        )

print(f"Parsed {len(recs)} records. Bodies extracted: {sum(1 for r in recs.values() if r['body'])}")
print("Missing bodies:", [k for k,v in recs.items() if not v['body']])
bysubj = defaultdict(set)
for r in recs.values(): bysubj[r['pk']].add(r['subject'])
print("\nSubjects per portfolio key:")
for pk in sorted(bysubj): print(f"  {pk}: {sorted(bysubj[pk])}")

# Save for later use
with open("/tmp/recs.json","w") as fh: json.dump(recs, fh, indent=1)
print("\nsaved /tmp/recs.json")
